.rs-table{width:calc(100% + 40px);border-collapse:collapse;margin-top:1rem;margin-bottom:1.5rem;margin-inline-start:-1.25rem;margin-inline-end:0;font-size:0.875rem}
@media (max-width: 640px){.rs-table{width:calc(100% + 2 * var(--pad));margin-inline-start:calc(-1 * var(--pad));margin-inline-end:calc(-1 * var(--pad));font-size:1rem}}
.rs-table-th{text-align:start;font-weight:600;color:var(--text);letter-spacing:-0.01em;padding-top:0.625rem;padding-bottom:0.625rem;padding-inline-start:0.75rem;padding-inline-end:1rem;border-bottom-width:2px;border-bottom-style:solid;border-bottom-color:var(--divider);font-size:0.8125rem}
.rs-table-th:last-child{text-align:end;padding-inline-end:1.25rem}
.rs-table-th:first-child{padding-inline-start:1.25rem}
@media (max-width: 640px){.rs-table-th{padding-top:0.875rem;padding-bottom:0.875rem;padding-inline-start:0.75rem;padding-inline-end:0.75rem;font-size:0.9375rem}}
.rs-table-td{padding-top:0.625rem;padding-bottom:0.625rem;padding-inline-start:0.75rem;padding-inline-end:1rem;color:var(--text-secondary);font-weight:500;letter-spacing:-0.01em;border-bottom-width:1px;border-bottom-style:solid;border-bottom-color:var(--divider);vertical-align:top;text-align:start}
.rs-table-td:first-child{padding-inline-start:1.25rem}
.rs-table-td:last-child{padding-inline-end:1.25rem;text-align:end}
@media (max-width: 640px){.rs-table-td{padding-top:0.875rem;padding-bottom:0.875rem;padding-inline-start:0.75rem;padding-inline-end:0.75rem}}
.rs-table-row{background-color:transparent}
.rs-table-row:nth-child(even){background-color:var(--table-alt)}
.rs-total-row{font-weight:500;color:var(--text);border-top-width:2px;border-top-style:solid;border-top-color:var(--divider);border-bottom-width:2px;border-bottom-style:solid;border-bottom-color:var(--divider);background-color:transparent}
.rs-table-total-cell{font-weight:500;color:var(--text);border-top-width:2px;border-bottom-width:2px}
